-- GPTZero — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GPTZero', NULL, 'https://gptzero.me', NULL, NULL, 'Перевіряє, чи текст написала людина, чи його згенерував штучний інтелект, і підсвічує окремі речення, схожі на написані AI. Безкоштовно можна перевіряти до 10 000 слів на місяць, більші обсяги — у платних планах.', 'Checks whether a text was written by a person or generated by AI and highlights individual sentences that look AI-written. Up to 10,000 words a month can be checked for free; larger volumes are available on paid plans.', 'GPTZero допомагає зрозуміти, чи текст створила людина, чи штучний інтелект. Достатньо вставити текст або завантажити файл — сервіс покаже загальний висновок і підсвітить речення, які найбільше схожі на згенеровані. Так легше побачити, яку саме частину роботи варто перечитати або обговорити з автором. Крім перевірки на AI, у платних планах є перевірка на плагіат і підказки щодо граматики. Є розширення для браузера Chrome, а для розробників — API, щоб вбудувати перевірку у власний сайт чи застосунок. Безкоштовний план розрахований на навчання і дозволяє перевіряти до 10 000 слів на місяць. Платні плани Essential, Premium і Professional відрізняються кількістю слів на місяць і додатковими функціями. Результат перевірки — це підказка, а не остаточний доказ: висновок про авторство варто робити разом із самим автором.', 'GPTZero helps you understand whether a text was written by a person or by artificial intelligence. Paste text or upload a file, and the service shows an overall result and highlights the sentences that look most like generated text, so it is easier to see which part of the work to reread or discuss with the author. Besides AI checking, paid plans add plagiarism scanning and grammar suggestions. There is a Chrome extension, and developers can use an API to add checking to their own site or app. The free plan is intended for education and covers up to 10,000 words a month. The paid Essential, Premium and Professional plans differ in the number of words per month and extra features. A check result is a hint, not final proof: conclusions about authorship are best made together with the author.', 'Перевірка тексту на ознаки створення штучним інтелектом
Підсвітка окремих речень, схожих на згенеровані
Перевірка на плагіат у платних планах
Розширення для браузера Chrome
API для вбудовування перевірки у власні сервіси
Безкоштовно до 10 000 слів на місяць', 'Checks text for signs of AI generation
Highlights individual sentences that look generated
Plagiarism scanning on paid plans
Chrome browser extension
API to build checking into your own services
Free for up to 10,000 words a month', 'Вчителі, викладачі й студенти, а також автори, редактори та рекрутери, яким потрібно перевірити, чи текст написала людина.', 'Teachers, lecturers and students, as well as writers, editors and recruiters who need to check whether a text was written by a person.', 'web', 'none', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gptzero.me' OR LOWER(`name`) = LOWER('GPTZero')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gptzero.me' OR LOWER(`name`) = LOWER('GPTZero')) ORDER BY `id` LIMIT 1);
