INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'GPTZero helps you understand whether a text was written by a person or by artificial intelligence. Paste text or upload a file, and the service shows an overall result and highlights the sentences that look most like generated text, so it is easier to see which part of the work to reread or discuss with the author. Besides AI checking, paid plans add plagiarism scanning and grammar suggestions. There is a Chrome extension, and developers can use an API to add checking to their own site or app. The free plan is intended for education and covers up to 10,000 words a month. The paid Essential, Premium and Professional plans differ in the number of words per month and extra features. A check result is a hint, not final proof: conclusions about authorship are best made together with the author.', 'manual' FROM DUAL WHERE @new = 1;
