-- Originality.ai — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Originality.ai', NULL, 'https://originality.ai', NULL, NULL, 'Перевіряє тексти на ознаки штучного інтелекту й на плагіат в одному місці, а також оцінює читабельність. Створений для видавців, власників сайтів і контент-команд; безкоштовно — 3 перевірки на день.', 'Checks texts for signs of AI and for plagiarism in one place and also rates readability. Built for publishers, website owners and content teams; 3 free checks a day.', 'Originality.ai допомагає видавцям і командам, що створюють контент, перевірити тексти перед публікацією. В одному звіті сервіс показує, чи схожий текст на згенерований штучним інтелектом, чи не збігається він з уже опублікованими матеріалами, і наскільки легко його читати. Текст можна вставити, завантажити файлом Word чи PDF або вказати адресу сторінки — у платних планах можна перевірити навіть увесь сайт. Сервіс враховує спроби переписати згенерований текст іншими інструментами. Є розширення для Chrome і Google Docs, яке ще й показує, як текст писався, щоб автор міг підтвердити своє авторство. Для команд є ролі й мітки для перевірок, а для великих обсягів — API. Безкоштовний план дає 3 перевірки на день до 2 000 слів кожна, платні плани Pro та Enterprise працюють на кредитах: один кредит — 100 слів.', 'Originality.ai helps publishers and content teams check texts before publishing. A single report shows whether a text looks AI-generated, whether it matches material that is already published, and how easy it is to read. Text can be pasted, uploaded as a Word or PDF file, or checked by page address — paid plans can even scan a whole website. The service also takes into account attempts to rewrite generated text with other tools. A Chrome and Google Docs extension also shows how a text was written, so authors can prove their authorship. Teams get roles and tags for scans, and there is an API for large volumes. The free plan gives 3 checks a day of up to 2,000 words each; the paid Pro and Enterprise plans work on credits, where one credit equals 100 words.', 'Перевірка на ознаки штучного інтелекту
Перевірка на плагіат
Оцінка читабельності та якості тексту
Перевірка окремих сторінок або цілого сайту за адресою
Розширення для Chrome і Google Docs із записом процесу написання
Керування командою та API в плані Enterprise', 'Checks for signs of AI
Plagiarism checking
Readability and content quality scoring
Scans single pages or a whole website by address
Chrome and Google Docs extension with writing replay
Team management and API on the Enterprise plan', 'Видавці, власники сайтів, контент-маркетологи й агенції, яким треба перевіряти тексти авторів перед публікацією.', 'Publishers, website owners, content marketers and agencies that need to check authors'' texts before publishing.', 'web', 'none', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'originality.ai' OR LOWER(`name`) = LOWER('Originality.ai')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'originality.ai' OR LOWER(`name`) = LOWER('Originality.ai')) ORDER BY `id` LIMIT 1);
