INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Originality.ai helps publishers and content teams check texts before publishing. A single report shows whether a text looks AI-generated, whether it matches material that is already published, and how easy it is to read. Text can be pasted, uploaded as a Word or PDF file, or checked by page address — paid plans can even scan a whole website. The service also takes into account attempts to rewrite generated text with other tools. A Chrome and Google Docs extension also shows how a text was written, so authors can prove their authorship. Teams get roles and tags for scans, and there is an API for large volumes. The free plan gives 3 checks a day of up to 2,000 words each; the paid Pro and Enterprise plans work on credits, where one credit equals 100 words.', 'manual' FROM DUAL WHERE @new = 1;
