-- Copyleaks — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Copyleaks', NULL, 'https://copyleaks.com', NULL, NULL, 'Шукає в текстах ознаки штучного інтелекту й плагіат, у тому числі перекладений з інших мов. Розпізнає AI-текст понад 30 мовами, а плагіат — понад 100; також перевіряє зображення на ознаки AI.', 'Looks for signs of AI and plagiarism in texts, including plagiarism translated from other languages. Detects AI text in 30+ languages and plagiarism in 100+; it also checks images for signs of AI.', 'Copyleaks перевіряє, чи текст написала людина, і чи не скопійований він з інших джерел. Сервіс працює з багатьма мовами: ознаки штучного інтелекту шукає понад 30 мовами, а плагіат — понад 100, і в старшому плані помічає навіть тексти, перекладені з іншої мови. Результати для AI і плагіату зводяться в один звіт. Можна перевіряти кілька файлів за раз, зберігати перевірки в акаунті, працювати прямо в Google Docs або через розширення для Chrome, Edge і Firefox. Також сервіс шукає ознаки штучного інтелекту на зображеннях. Для навчальних закладів і компаній є окремі рішення з інтеграцією в системи навчання та API. Плани для приватних користувачів і невеликих команд — Personal і Pro, рішення для освіти й великих компаній — за запитом.', 'Copyleaks checks whether a text was written by a person and whether it was copied from other sources. It works with many languages: it looks for signs of AI in 30+ languages and for plagiarism in 100+, and the higher plan even catches texts translated from another language. AI and plagiarism results are combined in one report. You can check several files at once, save scans to your account, and work directly in Google Docs or through the Chrome, Edge and Firefox extension. The service also looks for signs of AI in images. Schools and companies get separate solutions with learning-platform integrations and an API. Plans for individuals and small teams are Personal and Pro; solutions for education and large companies are available on request.', 'Перевірка тексту на ознаки штучного інтелекту понад 30 мовами
Перевірка на плагіат понад 100 мовами
Пошук плагіату, перекладеного з інших мов (план Pro)
Перевірка зображень на ознаки AI
Додаток для Google Docs і розширення для Chrome, Edge, Firefox
Інтеграції з системами навчання та API для закладів і компаній', 'Checks text for signs of AI in 30+ languages
Plagiarism checking in 100+ languages
Finds plagiarism translated from other languages (Pro plan)
Checks images for signs of AI
Google Docs add-on and Chrome, Edge, Firefox extension
Learning-platform integrations and API for schools and companies', 'Студенти, викладачі, автори й невеликі команди, а також навчальні заклади й компанії, яким потрібна багатомовна перевірка текстів.', 'Students, teachers, writers and small teams, as well as schools and companies that need multilingual text checking.', 'web', 'none', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'copyleaks.com' OR LOWER(`name`) = LOWER('Copyleaks')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'copyleaks.com' OR LOWER(`name`) = LOWER('Copyleaks')) ORDER BY `id` LIMIT 1);
