-- Turnitin — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Turnitin', NULL, 'https://www.turnitin.com', NULL, NULL, 'Набір інструментів для шкіл і університетів: перевіряє студентські роботи на збіги з іншими джерелами й ознаки тексту, написаного штучним інтелектом, допомагає з оцінюванням і відгуками. Надається закладам за ліцензією.', 'A set of tools for schools and universities: checks student work for matches with other sources and for signs of AI-written text, and helps with grading and feedback. Provided to institutions under a licence.', 'Turnitin працює з навчальними закладами й допомагає зберігати академічну доброчесність. Викладачі перевіряють роботи студентів на збіги з іншими джерелами та на ознаки тексту, написаного штучним інтелектом, а також ставлять оцінки й залишають відгуки в одному місці. Інструмент Turnitin Clarity показує, як студент працював над текстом і як використовував AI, щоб викладач бачив процес, а не лише результат. До набору також входять рішення для оцінювання паперових робіт і захищених іспитів, а для дослідників і видавців — окремий сервіс перевірки наукових текстів iThenticate. Доступ зазвичай надає заклад освіти: школа чи університет укладає ліцензію, а студенти й викладачі працюють через неї. Публічних цін на сайті немає — вартість обговорюється із закладом.', 'Turnitin works with educational institutions to help uphold academic integrity. Teachers check student work for matches with other sources and for signs of AI-written text, and grade and leave feedback in one place. Turnitin Clarity shows how a student worked on a text and used AI, so the teacher sees the process and not just the result. The suite also includes tools for grading paper-based work and secure exams, and a separate service for researchers and publishers, iThenticate. Access is usually provided by the institution: a school or university takes out a licence, and students and teachers use it. There are no public prices on the website — pricing is agreed with the institution.', 'Перевірка робіт на збіги з іншими джерелами
Виявлення ознак тексту, написаного штучним інтелектом
Turnitin Clarity: видно, як студент працював над текстом і використовував AI
Оцінювання та відгуки на роботи в одному місці
Рішення для паперових робіт і захищених іспитів
iThenticate для дослідників і видавців', 'Checks work for matches with other sources
Detects signs of AI-written text
Turnitin Clarity: see how a student wrote the text and used AI
Grading and feedback in one place
Tools for paper-based work and secure exams
iThenticate for researchers and publishers', 'Школи, університети та їхні викладачі й студенти, а також дослідники й наукові видавці. Доступ надається через ліцензію закладу.', 'Schools, universities and their teachers and students, as well as researchers and academic publishers. Access is provided through an institutional licence.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'turnitin.com' OR LOWER(`name`) = LOWER('Turnitin')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'turnitin.com' OR LOWER(`name`) = LOWER('Turnitin')) ORDER BY `id` LIMIT 1);
