INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Turnitin works with educational institutions to help uphold academic integrity. Teachers check student work for matches with other sources and for signs of AI-written text, and grade and leave feedback in one place. Turnitin Clarity shows how a student worked on a text and used AI, so the teacher sees the process and not just the result. The suite also includes tools for grading paper-based work and secure exams, and a separate service for researchers and publishers, iThenticate. Access is usually provided by the institution: a school or university takes out a licence, and students and teachers use it. There are no public prices on the website — pricing is agreed with the institution.', 'manual' FROM DUAL WHERE @new = 1;
