-- AI or Not — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AI or Not', NULL, 'https://www.aiornot.com', NULL, NULL, 'Швидко перевіряє, чи зображення створене штучним інтелектом. Також розпізнає AI-текст, відео, голос, музику й діпфейки. Для старту дає безкоштовні кредити, далі — недорогий план або оплата за використання.', 'Quickly checks whether an image was created by AI. It also detects AI-generated text, video, voice, music and deepfakes. Free credits to get started, then an inexpensive plan or pay-as-you-go.', 'AI or Not допомагає швидко зрозуміти, чи зображення зроблене людиною, чи згенероване штучним інтелектом: достатньо завантажити картинку й отримати відповідь. Окрім зображень, сервіс перевіряє текст, відео, голосові записи й музику та шукає діпфейки. Користуватися можна через сайт, а розробники підключають перевірку через API — ключ видається вже в безкоштовному плані. Безкоштовно дають $5 кредитів на старт, до мільйона слів перевірки тексту щомісяця і 20 перевірок зображень. План Pro коштує $5 на місяць і включає $10 кредитів щомісяця, які можна витрачати на будь-який тип перевірки, а невикористані переносяться на наступний місяць. Для великих обсягів, перепродажу чи розгортання на власних серверах є корпоративний план за запитом.', 'AI or Not helps you quickly find out whether an image was made by a person or generated by AI: upload a picture and get an answer. Besides images, the service checks text, video, voice recordings and music, and looks for deepfakes. You can use it on the website, and developers connect it through an API — a key is included even on the free plan. The free plan gives $5 in starter credits, up to a million words of text checking a month and 20 image checks. The Pro plan costs $5 a month and includes $10 of credits every month that can be spent on any type of check, with unused credits rolling over. For large volumes, resale or deployment on your own servers there is an enterprise plan on request.', 'Перевірка, чи зображення створене штучним інтелектом
Перевірка тексту, відео, голосу й музики на ознаки AI
Пошук діпфейків
API — ключ уже в безкоштовному плані
Кредити для будь-якого типу перевірки з перенесенням на наступний місяць', 'Checks whether an image was created by AI
Checks text, video, voice and music for signs of AI
Deepfake detection
API — key included on the free plan
Credits usable for any check type, rolling over monthly', 'Журналісти, модератори, дослідники й звичайні користувачі, яким треба швидко перевірити картинку чи інший контент, а також розробники, що вбудовують перевірку у свої сервіси.', 'Journalists, moderators, researchers and everyday users who need to check a picture or other content quickly, and developers building checks into their services.', 'web', 'none', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aiornot.com' OR LOWER(`name`) = LOWER('AI or Not')));
