-- Illuminarty — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Illuminarty', NULL, 'https://illuminarty.ai', NULL, NULL, 'Перевіряє, чи зображення або текст створені штучним інтелектом, і в платних планах показує на картинці ділянки, що найбільше схожі на згенеровані. Базова перевірка безкоштовна; є API для автоматичних перевірок.', 'Checks whether an image or text was created by AI and, on paid plans, marks the areas of a picture that look most generated. Basic checking is free; there is an API for automated checks.', 'Illuminarty допомагає зрозуміти, чи зображення або текст створені штучним інтелектом. Базова перевірка картинок і текстів безкоштовна і, за словами розробників, такою лишиться. У платних планах сервіс не лише дає загальну відповідь, а й показує на зображенні ділянки, які найбільше схожі на згенеровані, та підказує, яким генератором картинку могли створити. Для тексту так само можна побачити, які фрагменти викликають підозру. Розробники можуть підключити перевірку через API і автоматично перевіряти зображення у своєму сервісі: план Basic дозволяє до 10 000 запитів на день, Pro — до 40 000. Для спільнот і компаній, яким потрібні власні налаштування, необмежений API чи окремий сервер, є корпоративний план за запитом.', 'Illuminarty helps you find out whether an image or text was created by artificial intelligence. Basic checking of pictures and texts is free and, according to the developers, will stay that way. On paid plans the service not only gives an overall answer but also marks the areas of an image that look most generated and suggests which generator may have produced it. For text you can likewise see which fragments look suspicious. Developers can connect via an API and check images automatically in their own service: the Basic plan allows up to 10,000 requests a day, Pro up to 40,000. Communities and companies that need custom setup, unlimited API use or a dedicated server can get an enterprise plan on request.', 'Безкоштовна базова перевірка зображень і текстів
Позначення на зображенні ділянок, схожих на згенеровані (платні плани)
Підказка, яким генератором могли створити картинку
