INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Illuminarty helps you find out whether an image or text was created by artificial intelligence. Basic checking of pictures and texts is free and, according to the developers, will stay that way. On paid plans the service not only gives an overall answer but also marks the areas of an image that look most generated and suggests which generator may have produced it. For text you can likewise see which fragments look suspicious. Developers can connect via an API and check images automatically in their own service: the Basic plan allows up to 10,000 requests a day, Pro up to 40,000. Communities and companies that need custom setup, unlimited API use or a dedicated server can get an enterprise plan on request.', 'manual' FROM DUAL WHERE @new = 1;
