-- Hive Moderation — Освіта та знання › Детектори
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hive Moderation', NULL, 'https://hivemoderation.com', NULL, NULL, 'Виявляє згенеровані штучним інтелектом зображення, відео й аудіо та діпфейки. Можна спробувати у веб-демо, а платформи підключають перевірку через API й оплачують фактичне використання.', 'Detects AI-generated images, video and audio as well as deepfakes. You can try it in a web demo, and platforms connect checking through an API and pay for actual usage.', 'Hive Moderation допомагає онлайн-платформам знаходити контент, створений штучним інтелектом, і діпфейки. Сервіс перевіряє зображення, відео та аудіо й підказує, які матеріали варто позначити, відправити на ручний перегляд або прибрати. Спробувати перевірку можна у веб-демо прямо на сайті, а для постійної роботи її підключають через API до власного сайту чи застосунку. Крім пошуку AI-контенту, Hive має інструменти модерації небезпечного контенту, пошуку неправомірного використання чужих брендів і образів та панель для команд модерації. Для розробників і невеликих команд діє оплата за фактичне використання, після додавання способу оплати нараховується понад $50 стартових кредитів. Великим компаніям пропонують індивідуальні умови за запитом.', 'Hive Moderation helps online platforms find AI-created content and deepfakes. It checks images, video and audio and suggests which items to label, send for manual review or remove. You can try checking in a web demo on the website, and for ongoing use it is connected through an API to your own site or app. Besides AI content detection, Hive offers moderation of harmful content, detection of misuse of other people''s brands and likeness, and a dashboard for moderation teams. Developers and small teams pay for actual usage and receive $50+ in starter credits after adding a payment method. Large companies get custom terms on request.', 'Виявлення згенерованих штучним інтелектом зображень, відео й аудіо
Пошук діпфейків
Веб-демо для пробної перевірки
API для підключення до власних сервісів
Інструменти модерації та панель для команд', 'Detects AI-generated images, video and audio
Deepfake detection
Web demo for trying out checks
API for connecting to your own services
Moderation tools and a team dashboard', 'Соцмережі, маркетплейси та інші онлайн-платформи, їхні команди модерації й безпеки, а також розробники, які вбудовують перевірку в свої продукти.', 'Social networks, marketplaces and other online platforms, their moderation and trust & safety teams, and developers building checks into their products.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hivemoderation.com' OR LOWER(`name`) = LOWER('Hive Moderation')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hivemoderation.com' OR LOWER(`name`) = LOWER('Hive Moderation')) ORDER BY `id` LIMIT 1);
