-- Reality Defender — Освіта та знання › Детектори, Фінанси та юридичні › Безпека даних
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Reality Defender', NULL, 'https://www.realitydefender.com', NULL, NULL, 'Виявляє діпфейки й підроблені штучним інтелектом відео, аудіо, зображення та тексти, зокрема під час дзвінків і відеозустрічей у реальному часі. Розробникам — до 50 безкоштовних перевірок на місяць через API.', 'Detects deepfakes and AI-manipulated video, audio, images and text, including in real time during calls and video meetings. Developers get up to 50 free checks a month via the API.', 'Reality Defender допомагає компаніям і установам вчасно помітити діпфейки — підроблені за допомогою штучного інтелекту голоси, відео, зображення й тексти. Перевірка може працювати в реальному часі: у кол-центрі, на відеозустрічах, під час входу в системи й у спілкуванні з керівництвом, щоб шахраї не могли видати себе за іншу людину. Сервіс вбудовується в системи, якими організація вже користується. Для розробників є API і набори інструментів, з яких можна почати безкоштовно — до 50 перевірок аудіо або зображень на місяць. Серед галузей, з якими працює сервіс, — фінанси, кол-центри та державні установи. Повне корпоративне рішення надається за запитом.', 'Reality Defender helps companies and institutions spot deepfakes in time — voices, video, images and texts faked with artificial intelligence. Checking can run in real time: in contact centres, video meetings, sign-in flows and executive communications, so fraudsters cannot pose as someone else. The service integrates into systems the organisation already uses. Developers get an API and SDKs they can start with for free — up to 50 audio or image checks a month. Industries it works with include finance, call centres and government agencies. The full enterprise solution is available on request.', 'Виявлення діпфейків у відео, аудіо, зображеннях і текстах
Перевірка в реальному часі під час дзвінків і відеозустрічей
Захист кол-центрів і входу в системи від підміни особи
API та набори інструментів для розробників
До 50 безкоштовних перевірок аудіо або зображень на місяць', 'Detects deepfakes in video, audio, images and text
Real-time checking during calls and video meetings
Protects contact centres and sign-in flows from impersonation
API and SDKs for developers
Up to 50 free audio or image checks a month', 'Банки, кол-центри, державні установи та інші організації, яким потрібен захист від підробленої особи, а також розробники, що вбудовують перевірку діпфейків.', 'Banks, call centres, government agencies and other organisations that need protection against impersonation, and developers adding deepfake checks.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'realitydefender.com' OR LOWER(`name`) = LOWER('Reality Defender')));
