INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Reality Defender helps companies and institutions spot deepfakes in time — voices, video, images and texts faked with artificial intelligence. Checking can run in real time: in contact centres, video meetings, sign-in flows and executive communications, so fraudsters cannot pose as someone else. The service integrates into systems the organisation already uses. Developers get an API and SDKs they can start with for free — up to 50 audio or image checks a month. Industries it works with include finance, call centres and government agencies. The full enterprise solution is available on request.', 'manual' FROM DUAL WHERE @new = 1;
