-- Sensity AI — Освіта та знання › Детектори, Фінанси та юридичні › Безпека даних
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sensity AI', NULL, 'https://sensity.ai', NULL, NULL, 'Експертна перевірка відео, зображень і аудіо на діпфейки для розслідувань: аналізує саме зображення, звук, будову файлу й метадані. Працює в хмарі або на власних серверах організації, ціна — за запитом.', 'Expert deepfake analysis of video, images and audio for investigations: it examines the picture, the sound, the file structure and metadata. Runs in the cloud or on the organisation''s own servers; pricing on request.', 'Sensity AI допомагає організаціям з''ясувати, чи відео, зображення або аудіо не підроблені штучним інтелектом. Файл або посилання завантажують у застосунок, і за кілька секунд отримують докладну оцінку: сервіс перевіряє саме зображення до окремих пікселів, голос, будову файлу та метадані. Такий багатошаровий аналіз допомагає в розслідуваннях, коли потрібні ґрунтовні висновки, а не лише швидка відповідь. Рішення можна використовувати в хмарі або встановити на власних серверах, якщо дані не можна передавати назовні, а також підключити через API й автоматично перевіряти всі нові матеріали справи. Сервіс застосовують, зокрема, у протидії шахрайству, дезінформації та злочинам, пов''язаним із підробленими зображеннями, і для перевірки медіа. Публічних цін немає — умови обговорюються з організацією.', 'Sensity AI helps organisations find out whether video, images or audio have been faked with artificial intelligence. Upload a file or a link to the app and within seconds get a detailed assessment: the service examines the picture down to individual pixels, the voice, the file structure and metadata. This multi-layer analysis supports investigations that need thorough conclusions rather than just a quick answer. It can be used in the cloud or installed on the organisation''s own servers when data cannot leave the premises, and connected through an API to automatically screen all new case material. Uses include fighting fraud, disinformation and crimes involving faked images, and media authentication. There are no public prices — terms are agreed with the organisation.', 'Перевірка відео, зображень і аудіо на діпфейки
Аналіз зображення, голосу, будови файлу й метаданих
Розгортання в хмарі або на власних серверах
API для автоматичної перевірки матеріалів
Застосування в розслідуваннях шахрайства й дезінформації', 'Deepfake checks for video, images and audio
Analysis of image, voice, file structure and metadata
Cloud or on-premise deployment
API for automatic screening of material
Used in fraud and disinformation investigations', 'Правоохоронні органи, державні установи, компанії та медіа, яким потрібна ґрунтовна перевірка медіафайлів на підробку.', 'Law enforcement, government agencies, companies and media organisations that need thorough checks of media files for manipulation.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sensity.ai' OR LOWER(`name`) = LOWER('Sensity AI')));
SET @new = ROW_COUNT();
