INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Sensity AI helps organisations find out whether video, images or audio have been faked with artificial intelligence. Upload a file or a link to the app and within seconds get a detailed assessment: the service examines the picture down to individual pixels, the voice, the file structure and metadata. This multi-layer analysis supports investigations that need thorough conclusions rather than just a quick answer. It can be used in the cloud or installed on the organisation''s own servers when data cannot leave the premises, and connected through an API to automatically screen all new case material. Uses include fighting fraud, disinformation and crimes involving faked images, and media authentication. There are no public prices — terms are agreed with the organisation.', 'manual' FROM DUAL WHERE @new = 1;
