-- Pindrop — Освіта та знання › Детектори, Фінанси та юридичні › Безпека даних
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pindrop', NULL, 'https://www.pindrop.com', NULL, NULL, 'Розпізнає клоновані й синтетичні голоси, діпфейки та AI-ботів під час телефонних дзвінків і відеозустрічей, а також оцінює ризик шахрайства в реальному часі. Для кол-центрів, банків і страхових компаній.', 'Detects cloned and synthetic voices, deepfakes and AI bots during phone calls and video meetings, and assesses fraud risk in real time. For contact centres, banks and insurers.', 'Pindrop допомагає компаніям переконатися, що на лінії справді та людина, за яку себе видає. Під час телефонного дзвінка чи відеозустрічі сервіс у реальному часі перевіряє, чи голос не клонований і не синтезований штучним інтелектом, чи не спілкується замість людини AI-бот, і оцінює ризик шахрайства. Також він допомагає впізнавати постійних клієнтів без зайвих запитань і виявляти фіктивних кандидатів на співбесідах. Pindrop підключається до платформ кол-центрів і до Zoom, Microsoft Teams та Webex. Серед галузей, з якими працює сервіс, — фінанси, страхування, охорона здоров''я та роздрібна торгівля. Публічних цін немає — вартість обговорюється з компанією.', 'Pindrop helps companies make sure the person on the line really is who they claim to be. During a phone call or video meeting it checks in real time whether a voice is cloned or synthesised by AI, whether an AI bot is speaking instead of a person, and assesses fraud risk. It also helps recognise returning customers without extra questions and spot fake job candidates in interviews. Pindrop connects to contact-centre platforms and to Zoom, Microsoft Teams and Webex. Industries it works with include finance, insurance, healthcare and retail. There are no public prices — pricing is agreed with the company.', 'Виявлення клонованих і синтетичних голосів у дзвінках
Пошук діпфейків на відеозустрічах
Розпізнавання AI-ботів замість людей
Оцінка ризику шахрайства в реальному часі
Інтеграція з платформами кол-центрів, Zoom, Microsoft Teams і Webex', 'Detects cloned and synthetic voices in calls
Finds deepfakes in video meetings
Spots AI bots posing as people
Real-time fraud risk assessment
Integrates with contact-centre platforms, Zoom, Microsoft Teams and Webex', 'Кол-центри, банки, страхові компанії та інші організації, які обслуговують клієнтів телефоном або відеозв''язком і хочуть захиститися від шахраїв.', 'Contact centres, banks, insurers and other organisations that serve customers by phone or video and want protection from fraudsters.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-09-28 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pindrop.com' OR LOWER(`name`) = LOWER('Pindrop')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pindrop.com' OR LOWER(`name`) = LOWER('Pindrop')) ORDER BY `id` LIMIT 1);
