SELECT
    (SELECT COUNT(*) FROM `product_subcategories` ps JOIN `subcategories` s ON s.`id` = ps.`subcategory_id` JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'education-knowledge' AND s.`slug` = 'detectors') AS detectors_products,
    (SELECT COUNT(*) FROM `product_subcategories` ps JOIN `subcategories` s ON s.`id` = ps.`subcategory_id` JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'finance-legal' AND s.`slug` = 'data-security') AS data_security_products;
